<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';

$action=(string)($_GET['action']??'');
if($action==='login'){ $b=body(); $s=db()->prepare('SELECT id,email,password_hash FROM users WHERE LOWER(email)=LOWER(?) LIMIT 1'); $s->execute([(string)($b['email']??'')]); $u=$s->fetch(); if(!$u||!password_verify((string)($b['password']??''),$u['password_hash']))json_response(['error'=>'Fel e-post eller lösenord.'],401); start_secure_session(); session_regenerate_id(true); $_SESSION['user_id']=$u['id']; $_SESSION['email']=$u['email']; json_response(['data'=>['user'=>['id'=>$u['id'],'email'=>$u['email']]]]); }
if($action==='user'){ start_secure_session(); json_response(['data'=>['user'=>empty($_SESSION['user_id'])?null:['id'=>$_SESSION['user_id'],'email'=>$_SESSION['email']]]]); }
if($action==='logout'){ start_secure_session(); $_SESSION=[]; session_destroy(); json_response(['data'=>true]); }
if($action==='request-password-reset'){ $b=body(); $s=db()->prepare('SELECT id,email FROM users WHERE LOWER(email)=LOWER(?)'); $s->execute([(string)($b['email']??'')]); if($u=$s->fetch()){ $token=bin2hex(random_bytes(32)); $expiry=(config()['db_driver']??'mysql')==='sqlite'?"datetime('now','+1 hour')":'DATE_ADD(NOW(),INTERVAL 1 HOUR)'; db()->prepare("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,$expiry)")->execute([$u['id'],hash('sha256',$token)]); $c=config(); $url=rtrim($c['site_url'],'/').'/reset-password?token='.rawurlencode($token); @mail($u['email'],'Återställ lösenord – Ilinium',"Öppna länken inom en timme:\n\n$url",'From: '.$c['mail_from']); } json_response(['data'=>true]); }
if($action==='update-password'){ $b=body(); $pw=(string)($b['password']??''); if(strlen($pw)<12)json_response(['error'=>'Lösenordet måste vara minst 12 tecken.'],422); start_secure_session(); $uid=$_SESSION['user_id']??null; if(!$uid&&isset($b['token'])){ $now=(config()['db_driver']??'mysql')==='sqlite'?"datetime('now')":'NOW()'; $s=db()->prepare("SELECT user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>$now"); $s->execute([hash('sha256',(string)$b['token'])]); $uid=$s->fetchColumn(); if($uid)db()->prepare("UPDATE password_reset_tokens SET used_at=$now WHERE token_hash=?")->execute([hash('sha256',(string)$b['token'])]); } if(!$uid)json_response(['error'=>'Länken är ogiltig eller har gått ut.'],401); db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$uid]); json_response(['data'=>true]); }
if($action==='upload'){ require_admin(); if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)json_response(['error'=>'Uppladdningen misslyckades.'],422); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['file']['tmp_name']); $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null; if(!$ext)json_response(['error'=>'Ogiltig bildtyp.'],422); $folder=preg_replace('/[^a-zA-Z0-9_-]/','',(string)explode('/',(string)($_POST['path']??'media'))[0])?:'media'; $dir=dirname(__DIR__).'/uploads/'.$folder; if(!is_dir($dir))mkdir($dir,0755,true); $name=bin2hex(random_bytes(12)).'.'.$ext; if(!move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name))json_response(['error'=>'Kunde inte spara bilden.'],500); json_response(['data'=>['path'=>'/uploads/'.$folder.'/'.$name]]); }

$columns=[
'site_settings'=>['id','content','updated_at'],'site_settings_draft'=>['id','content','updated_at'],
'content_versions'=>['id','content','note','created_by','created_at'],'treatment_categories'=>['id','name','sort_order'],
'treatments'=>['id','category_id','name','description','price','price_from','image_url','featured','visible','sort_order'],
'staff'=>['id','name','role','bio','phone','image_url','facebook_url','instagram_url','visible','sort_order'],
'gallery_images'=>['id','url','alt','caption','visible','sort_order'],'opening_hours'=>['weekday','opens','closes','closed'],
'special_opening_hours'=>['id','date','label','opens','closes','closed']];
$public=['site_settings','treatment_categories','treatments','staff','gallery_images','opening_hours','special_opening_hours'];
$table=(string)($_GET['resource']??''); if($table==='user_roles'){ $u=require_admin(); json_response(['data'=>[['user_id'=>$u['id'],'role'=>'admin','id'=>$u['id']]]]); }
if(!isset($columns[$table]))json_response(['error'=>'Ogiltig resurs.'],404);
$method=$_SERVER['REQUEST_METHOD']; if($method!=='GET')require_admin(); elseif(!in_array($table,$public,true))require_admin();
$filters=json_decode((string)($_GET['filters']??'[]'),true)?:[]; $where=[];$params=[];
foreach($filters as $f){$col=(string)($f['column']??'');if(!in_array($col,$columns[$table],true))continue;$where[]="`$col`=?";$params[]=$f['value'];}
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
if($method==='GET'){ $requested=(string)($_GET['fields']??'*'); $fields='*'; if($requested!=='*'){ $list=array_values(array_filter(array_map('trim',explode(',',$requested)),fn($c)=>in_array($c,$columns[$table],true))); if($list)$fields=implode(',',array_map(fn($c)=>"`$c`",$list)); } $sql="SELECT $fields FROM `$table`$whereSql"; $order=json_decode((string)($_GET['order']??''),true); if(is_array($order)&&in_array($order['column']??'',$columns[$table],true))$sql.=' ORDER BY `'.$order['column'].'` '.(!empty($order['ascending'])?'ASC':'DESC'); $limit=min(1000,max(1,(int)($_GET['limit']??1000)));$sql.=" LIMIT $limit";$s=db()->prepare($sql);$s->execute($params);json_response(['data'=>array_map('normalize_row',$s->fetchAll())]); }
if($method==='DELETE'){ $s=db()->prepare("DELETE FROM `$table`$whereSql");$s->execute($params);json_response(['data'=>true]); }
$payload=body(); $rows=array_is_list($payload)?$payload:[$payload]; $operation=(string)($_GET['action']??'insert');
if($method==='PATCH'){ $row=$rows[0]??[];$sets=[];$values=[];foreach($row as $k=>$v)if(in_array($k,$columns[$table],true)&&!in_array($k,['id','updated_at','created_at'],true)){$sets[]="`$k`=?";$values[]=($k==='content'?json_encode($v,JSON_UNESCAPED_UNICODE):$v);}if(!$sets)json_response(['error'=>'Inga giltiga fält.'],422);$s=db()->prepare("UPDATE `$table` SET ".implode(',',$sets).$whereSql);$s->execute([...$values,...$params]);json_response(['data'=>true]);}
$out=[];foreach($rows as $row){if(!is_array($row))continue;if(!isset($row['id'])&&$table!=='opening_hours')$row['id']=uuid();$valid=[];foreach($row as $k=>$v)if(in_array($k,$columns[$table],true)&&!in_array($k,['updated_at','created_at'],true))$valid[$k]=$k==='content'?json_encode($v,JSON_UNESCAPED_UNICODE):$v;$cols=array_keys($valid);$marks=implode(',',array_fill(0,count($cols),'?'));$sqlite=(config()['db_driver']??'mysql')==='sqlite';$sql=($operation==='upsert'&&$sqlite?'INSERT OR REPLACE':'INSERT').' INTO `'.$table.'` (`'.implode('`,`',$cols).'`) VALUES ('.$marks.')';if($operation==='upsert'&&!$sqlite)$sql.=' ON DUPLICATE KEY UPDATE '.implode(',',array_map(fn($c)=>"`$c`=VALUES(`$c`)",array_filter($cols,fn($c)=>!in_array($c,['id','weekday'],true))));$s=db()->prepare($sql);$s->execute(array_values($valid));$out[]=$row;}
json_response(['data'=>$out]);
